```python
def char_frequency(text):
    """
    Returns a dictionary with the frequency count of each character in a given string.

    Args:
        text (str): The input string to analyze

    Returns:
        dict: A dictionary where keys are characters and values are their frequency counts

    Examples:
        >>> char_frequency("hello")
        {'h': 1, 'e': 1, 'l': 2, 'o': 1}

        >>> char_frequency("aabbcc")
        {'a': 2, 'b': 2, 'c': 2}

        >>> char_frequency("")
        {}
    """
    if not text:
        return {}

    frequency = {}
    for char in text:
        frequency[char] = frequency.get(char, 0) + 1

    return frequency

# Example usage and testing
if __name__ == "__main__":
    # Test cases
    print(char_frequency("hello"))        # {'h': 1, 'e': 1, 'l': 2, 'o': 1}
    print(char_frequency("programming"))  # {'p': 1, 'r': 2, 'o': 1, 'g': 2, 'a': 1, 'm': 2, 'i': 1, 'n': 1}
    print(char_frequency(""))            # {}
    print(char_frequency("a"))           # {'a': 1}
    print(char_frequency("aaa"))         # {'a': 3}
```

